package main

import (
    "crypto/rand"
    "encoding/base64"
    "errors"
    "time"
)

const challengeTTL = 2 * time.Minute

var errChallengeExpired = errors.New("challenge expired")

type challenge struct {
    value   string
    expires time.Time
}

func newChallenge(now time.Time) (challenge, error) {
    buf := make([]byte, 32)
    if _, err := rand.Read(buf); err != nil {
        return challenge{}, err
    }
    value := base64.RawURLEncoding.EncodeToString(buf)
    return challenge{value, now.Add(challengeTTL)}, nil
}

func (c challenge) verify(answer string, now time.Time) error {
    if now.After(c.expires) {
        return errChallengeExpired
    }
    if answer != c.value {
        return errors.New("challenge mismatch")
    }
    return nil
}

