import "sync"

// KeyStore runs each idempotency key once and replays its refund.
type KeyStore struct {
    mu   sync.Mutex
    done map[string]Refund
}

func (s *KeyStore) Once(key string, run func() (Refund, error)) (Refund, error) {
    s.mu.Lock()
    defer s.mu.Unlock()
    if refund, ok := s.done[key]; ok {
        return refund, nil
    }
    refund, err := run()
    if err == nil {
        s.done[key] = refund
    }
    return refund, err
}

