package webhooks

import (
    "math/rand/v2"
    "time"
)

const (
    maxAttempts = 5
    firstDelay  = 15 * time.Second
)

// backoff doubles the delay after each attempt, plus up to 10% jitter.
func backoff(attempt int) time.Duration {
    delay := firstDelay << (attempt - 1)
    return delay + rand.N(delay/10)
}

