package webhooks

import (
    "context"
    "time"
)

func (d *Deliverer) deliver(ctx context.Context, e Event) error {
    var err error
    for attempt := 1; attempt <= maxAttempts; attempt++ {
        if err = d.post(ctx, e); err == nil {
            return nil
        }
        if attempt == maxAttempts {
            break
        }
        wait := backoff(attempt)
        d.log.Warn("delivery failed", "event", e.ID, "attempt", attempt, "retry", wait)
        select {
        case <-ctx.Done():
            return ctx.Err()
        case <-time.After(wait):
        }
    }
    return d.deadLetter(ctx, e, err)
}

